(() => {
  const IMPORT_ID = 'basemap';
  const schema = map.getSchema(IMPORT_ID) || {};

  const entries = Object.entries(schema).map(([name, spec]) => {
    const md = (spec && spec.metadata) || {};
    return {
      name,
      spec: spec || {},
      text: [name, md['mapbox:title'] || '', md['mapbox:description'] || ''].join(' | ').toLowerCase()
    };
  });

  const valuesOf = (e) => (e && Array.isArray(e.spec.values) ? e.spec.values : []);
  const read = (name) => map.getConfigProperty(IMPORT_ID, name);

  // Locate the theme selector setting (normally "theme").
  const themeEntry =
    entries.find((e) => e.name === 'theme') ||
    entries.find((e) => /\btheme\b/.test(e.text) && !/data|lut|look[\s-]*up/.test(e.name) && valuesOf(e).length) ||
    entries.find((e) => /\btheme\b/.test(e.text) && !/data|lut|look[\s-]*up/.test(e.name));

  // Locate the custom theme LUT setting (normally "theme-data").
  const dataEntry =
    entries.find((e) => e.name === 'theme-data') ||
    entries.find((e) => e !== themeEntry && !valuesOf(e).length && /theme[\s_-]*data|\blut\b|look[\s-]*up/.test(e.text));

  // Build a 32x32x32 colour lookup table (laid out as a 1024x32 strip: x = b*32 + r, y = g)
  // whose every output is a neutral grey (R = G = B) equal to the input's luminance.
  const makeGreyLut = (N = 32) => {
    const toLin = (c) => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
    const toSrgb = (c) => (c <= 0.0031308 ? c * 12.92 : 1.055 * Math.pow(c, 1 / 2.4) - 0.055);
    const canvas = document.createElement('canvas');
    canvas.width = N * N;
    canvas.height = N;
    const ctx = canvas.getContext('2d');
    const img = ctx.createImageData(N * N, N);
    const d = img.data;
    for (let g = 0; g < N; g++) {
      for (let b = 0; b < N; b++) {
        for (let r = 0; r < N; r++) {
          const y =
            0.2126 * toLin(r / (N - 1)) +
            0.7152 * toLin(g / (N - 1)) +
            0.0722 * toLin(b / (N - 1));
          const v = Math.round(255 * Math.min(1, Math.max(0, toSrgb(y))));
          const i = (g * N * N + b * N + r) * 4;
          d[i] = v;
          d[i + 1] = v;
          d[i + 2] = v;
          d[i + 3] = 255;
        }
      }
    }
    ctx.putImageData(img, 0, 0);
    return canvas.toDataURL('image/png').split(',')[1];
  };

  let applied = false;

  // Preferred: custom theme with a strictly greyscale LUT (guarantees zero saturation).
  if (themeEntry && dataEntry && (!valuesOf(themeEntry).length || valuesOf(themeEntry).includes('custom'))) {
    const lut = makeGreyLut();
    map.setConfigProperty(IMPORT_ID, dataEntry.name, lut);
    map.setConfigProperty(IMPORT_ID, themeEntry.name, 'custom');
    applied = read(themeEntry.name) === 'custom' && read(dataEntry.name) === lut;
    if (!applied) console.warn('Greyscale LUT was not accepted by the basemap config; falling back.', {
      theme: read(themeEntry.name)
    });
  }

  // Fallback: the style's built-in monochrome theme.
  if (!applied && themeEntry) {
    const mono = valuesOf(themeEntry).find((v) => /mono|gr[ae]y/i.test(String(v))) || 'monochrome';
    map.setConfigProperty(IMPORT_ID, themeEntry.name, mono);
    applied = read(themeEntry.name) === mono;
    if (!applied) console.warn('Monochrome theme was not accepted by the basemap config; falling back.', {
      theme: read(themeEntry.name)
    });
  }

  // Last resort: desaturate the rendered map canvas.
  if (!applied) {
    map.getCanvas().style.filter = 'grayscale(1)';
    console.warn('No usable theme setting found in the basemap schema; applied a CSS greyscale filter to the map canvas.');
  }

  map.triggerRepaint();
})();

