const LUT = 'LUT_BASE64';
const schema = map.getSchema('basemap') || {};
const entries = Object.entries(schema);
const describe = ([name, def]) =>
  [name, def?.metadata?.['mapbox:title'], def?.metadata?.['mapbox:description']]
    .filter(Boolean).join(' ').toLowerCase();

const themeKey = schema['theme']
  ? 'theme'
  : (entries.find(([, def]) => Array.isArray(def?.values) && def.values.includes('custom')) || [])[0];

const dataKey = schema['theme-data']
  ? 'theme-data'
  : (entries.find((e) => e[0] !== themeKey && /\blut\b|look[\s-]?up|base64|theme[\s-]?data|custom theme/.test(describe(e))) || [])[0];

if (!dataKey) throw new Error('No LUT/theme-data setting found in the basemap schema');

if (themeKey) map.setConfigProperty('basemap', themeKey, 'custom');
map.setConfigProperty('basemap', dataKey, LUT);

if (themeKey && map.getConfigProperty('basemap', themeKey) !== 'custom') {
  console.warn(`Basemap setting "${themeKey}" did not accept "custom"`);
}
if (map.getConfigProperty('basemap', dataKey) !== LUT) {
  console.warn(`Basemap setting "${dataKey}" did not accept the LUT data`);
}

