(function () {
  var IMPORT_ID = 'basemap';
  var TARGET = 'dusk';
  var schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};
  var names = Object.keys(schema);

  function describe(name) {
    var entry = schema[name] || {};
    var meta = entry.metadata || {};
    return [name, meta['mapbox:title'], meta['mapbox:description']]
      .filter(Boolean).join(' ').toLowerCase();
  }

  function offersDusk(name) {
    var values = (schema[name] && schema[name].values) || [];
    return values.some(function (v) { return String(v).toLowerCase() === TARGET; });
  }

  var key = null;
  if (names.indexOf('lightPreset') !== -1) key = 'lightPreset';
  if (!key) key = names.find(offersDusk) || null;
  if (!key) {
    key = names.find(function (n) {
      var t = describe(n);
      return /light|lighting|time of day/.test(t) && /preset|dusk|dawn|night|time of day/.test(t);
    }) || null;
  }
  if (!key) key = 'lightPreset';

  var value = TARGET;
  var entry = schema[key];
  if (entry && Array.isArray(entry.values)) {
    var match = entry.values.find(function (v) { return String(v).toLowerCase() === TARGET; });
    if (match !== undefined) value = match;
  }

  map.setConfigProperty(IMPORT_ID, key, value);

  var actual = map.getConfigProperty(IMPORT_ID, key);
  if (String(actual).toLowerCase() !== TARGET) {
    console.warn('Dusk light preset was not applied. Setting "' + key + '" reads back as:', actual,
      'Available basemap settings:', names.map(function (n) {
        var m = (schema[n] && schema[n].metadata) || {};
        return { name: n, title: m['mapbox:title'], description: m['mapbox:description'], values: schema[n] && schema[n].values };
      }));
  }
})();

