answer:
(() => {
  const IMPORT_ID = 'basemap';
  const schema = map.getSchema(IMPORT_ID) || {};
  const names = Object.keys(schema);

  const describe = (name) => {
    const md = (schema[name] && schema[name].metadata) || {};
    return [name, md['mapbox:title'], md['mapbox:description']]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
  };

  const isBoolean = (name) => {
    const def = schema[name] || {};
    return (
      def.type === 'checkbox' ||
      typeof def.default === 'boolean' ||
      typeof map.getConfigProperty(IMPORT_ID, name) === 'boolean'
    );
  };

  const placeWords = /(place|settlement|cit(y|ies)|town|village|neighbo(u)?rhood|locality|suburb)/;
  const excludeWords = /(point.?of.?interest|\bpoi\b|road|street|transit|landmark|building|admin)/;

  let targets = names.filter((n) => n === 'showPlaceLabels');

  names.forEach((n) => {
    if (targets.includes(n) || !isBoolean(n)) return;
    const t = describe(n);
    if (/label/.test(t) && placeWords.test(t) && !excludeWords.test(t)) targets.push(n);
  });

  if (!targets.length) {
    console.warn('No basemap config property found for place labels. Available:', names);
    return;
  }

  const verified = [];
  targets.forEach((name) => {
    const hideValue = /^hide|\bhide/.test(describe(name).split(' ')[0]) ? true : false;
    map.setConfigProperty(IMPORT_ID, name, hideValue);
    const actual = map.getConfigProperty(IMPORT_ID, name);
    if (actual === hideValue) {
      verified.push(name);
    } else {
      console.warn(`Config property "${name}" did not take the value ${hideValue}; read back:`, actual);
    }
  });

  if (!verified.length) {
    console.warn('Place labels could not be hidden; no setting was confirmed.', targets);
  }
})();

