answer:
(function () {
  const IMPORT_ID = 'basemap';
  const TARGET = '#1a237e';

  const schema = map.getSchema(IMPORT_ID) || {};
  const keys = Object.keys(schema);

  const describe = (key) => {
    const entry = schema[key] || {};
    const meta = entry.metadata || {};
    return [key, meta['mapbox:title'], meta['mapbox:description']]
      .filter(Boolean)
      .join(' ')
      .replace(/([a-z])([A-Z])/g, '$1 $2')
      .toLowerCase();
  };

  const isColorOption = (key) => {
    const entry = schema[key] || {};
    return entry.type === 'color' || /colou?r/.test(describe(key));
  };

  let key = keys.includes('colorPlaceLabels') && isColorOption('colorPlaceLabels') ? 'colorPlaceLabels' : null;

  if (!key) {
    const scored = keys
      .filter(isColorOption)
      .map((k) => {
        const t = describe(k);
        const name = k.toLowerCase();
        if (/poi|point\s*of\s*interest|pointofinterest|road|street|transit|admin|boundar/.test(name)) return null;
        let score = 0;
        if (/place/.test(t)) score += 3;
        if (/label|name/.test(t)) score += 2;
        if (/\bcit(y|ies)\b|\btowns?\b|neighbou?rhoods?|settlements?|localit(y|ies)/.test(t)) score += 3;
        if (/point\s*of\s*interest|\bpoi\b/.test(t)) score -= 4;
        if (/\broads?\b|\bstreets?\b|transit/.test(t)) score -= 2;
        return score >= 5 ? { k, score } : null;
      })
      .filter(Boolean)
      .sort((a, b) => b.score - a.score);
    if (scored.length) key = scored[0].k;
  }

  if (!key) {
    throw new Error('No place-label colour setting found in the basemap schema. Available options: ' + keys.join(', '));
  }

  map.setConfigProperty(IMPORT_ID, key, TARGET);

  const toRGB = (v) => {
    if (v == null) return null;
    if (typeof v === 'object' && !Array.isArray(v) && 'r' in v && 'g' in v && 'b' in v) {
      const s = v.r <= 1 && v.g <= 1 && v.b <= 1 ? 255 : 1;
      return [v.r, v.g, v.b].map((c) => Math.round(c * s));
    }
    if (typeof v !== 'string') return null;
    const s = v.trim().toLowerCase();
    let m = s.match(/^#([0-9a-f]{6})([0-9a-f]{2})?$/);
    if (m) return [0, 2, 4].map((i) => parseInt(m[1].slice(i, i + 2), 16));
    m = s.match(/^#([0-9a-f]{3})$/);
    if (m) return m[1].split('').map((c) => parseInt(c + c, 16));
    m = s.match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/);
    if (m) return [m[1], m[2], m[3]].map((n) => Math.round(parseFloat(n)));
    return null;
  };

  const readBack = map.getConfigProperty(IMPORT_ID, key);
  const want = toRGB(TARGET);
  const got = toRGB(readBack);

  if (got && got.every((c, i) => c === want[i])) {
    console.log(`Set basemap config "${key}" to ${TARGET}; read back:`, readBack);
  } else {
    console.warn(`Set basemap config "${key}" to ${TARGET}, but read back:`, readBack);
  }
})();

