(function () {
  const IMPORT_ID = 'basemap';
  const KNOWN_NAME = 'showAdminBoundaries';

  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};
  const candidates = [];

  if (Object.prototype.hasOwnProperty.call(schema, KNOWN_NAME)) {
    candidates.push(KNOWN_NAME);
  }

  for (const [name, def] of Object.entries(schema)) {
    if (candidates.includes(name)) continue;
    const meta = (def && def.metadata) || {};
    const text = [name, meta['mapbox:title'], meta['mapbox:description']]
      .filter(Boolean)
      .join(' ');
    const isBoolean = def && (def.type === 'boolean' || typeof def.default === 'boolean');
    const mentionsBorders = /admin|boundar|border/i.test(text);
    const isToggle = /show|visib|display|toggle|hide/i.test(text);
    const isLabelOrColor = /label|colou?r/i.test(name);
    if (isBoolean && mentionsBorders && isToggle && !isLabelOrColor) {
      candidates.push(name);
    }
  }

  if (candidates.length === 0) {
    candidates.push(KNOWN_NAME);
    console.warn(
      'No border-related setting found in the basemap schema; trying "' + KNOWN_NAME + '" anyway.'
    );
  }

  const results = candidates.map(function (name) {
    map.setConfigProperty(IMPORT_ID, name, false);
    const value = map.getConfigProperty(IMPORT_ID, name);
    return { name: name, value: value, inSchema: Object.prototype.hasOwnProperty.call(schema, name) };
  });

  const applied = results.filter(function (r) { return r.value === false && r.inSchema; });

  if (applied.length > 0) {
    console.log(
      'Country and state border lines hidden via: ' +
        applied.map(function (r) { return r.name; }).join(', ')
    );
  } else {
    console.warn(
      'Could not confirm that border lines were hidden. Results:',
      results,
      'Basemap schema:',
      schema
    );
  }
})();

