(() => {
  const IMPORT_ID = 'basemap';
  const ORANGE = '#ff8c00';

  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};
  const names = Object.keys(schema);

  const describe = (name) => {
    const meta = (schema[name] && schema[name].metadata) || {};
    return [name, meta['mapbox:title'], meta['mapbox:description']]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
  };

  const isBoundary = (name) => /admin|boundar|border/.test(describe(name)) && !/label/.test(describe(name));
  const isColor = (name) => (schema[name] && schema[name].type === 'color') || /colou?r/.test(describe(name));
  const isToggle = (name) => (schema[name] && schema[name].type === 'boolean') || /^show/i.test(name);

  let colorKeys = names.filter((n) => isBoundary(n) && isColor(n));
  if (colorKeys.includes('colorAdminBoundaries')) colorKeys = ['colorAdminBoundaries'];
  if (!colorKeys.length && !names.length) colorKeys = ['colorAdminBoundaries'];

  if (!colorKeys.length) {
    console.error('No admin boundary color setting found in the basemap schema:', schema);
    return;
  }

  const toggleKeys = names.filter((n) => isBoundary(n) && isToggle(n) && !isColor(n));
  toggleKeys.forEach((key) => {
    if (map.getConfigProperty(IMPORT_ID, key) === false) {
