answer:
(() => {
  const IMPORT_ID = 'basemap';
  const TARGET = '#fff3c4';

  const schema = map.getSchema(IMPORT_ID) || {};
  const areaRe = /commercial|shopping|business|retail|\bshops?\b/i;

  const meta = (entry) => (entry && entry.metadata) || {};
  const isColorSetting = (name, entry) => {
    const m = meta(entry);
    return /^colou?r/i.test(name) ||
      (entry && entry.type === 'color') ||
      /colou?r/i.test(String(m['mapbox:title'] || ''));
  };

  const candidates = Object.entries(schema)
    .map(([name, entry]) => {
      const m = meta(entry);
      const title = String(m['mapbox:title'] || '');
      const desc = String(m['mapbox:description'] || '');
      let score = 0;
      if (name === 'colorCommercial') score += 100;
      if (/commercial/i.test(name)) score += 50;
      if (areaRe.test(name)) score += 30;
      if (areaRe.test(title)) score += 20;
      if (areaRe.test(desc)) score += 10;
      if (/label|icon|text|poi|pointofinterest/i.test(name + ' ' + title)) score -= 40;
      if (!isColorSetting(name, entry)) score -= 100;
      return { name, title, desc, score };
    })
    .filter((c) => c.score > 0)
    .sort((a, b) => b.score - a.score);

  if (!candidates.length) {
    console.warn(
      'No commercial/shopping/business area colour setting found in the "' + IMPORT_ID + '" schema. Available settings:',
      Object.keys(schema)
    );
    return;
  }

  const toRgb = (v) => {
    if (v == null) return null;
    if (typeof v === 'object') {
      if ('r' in v && 'g' in v && 'b' in v) {
        const scale = Math.max(v.r, v.g, v.b) <= 1 ? 255 : 1;
        return [v.r * scale, v.g * scale, v.b * scale].map(Math.round);
      }
      return toRgb(JSON.stringify(v).match(/#[0-9a-f]{3,8}|rgba?\([^)]*\)/i)?.[0]);
    }
    const s = String(v).trim().toLowerCase();
    let m = s.match(/^#([0-9a-f]{6})([0-9a-f]{2})?$/);
    if (m) return [0, 2, 4].map((i) => parseInt(m[1].slice(i, i + 2), 16));
    m = s.match(/^#([0-9a-f]{3})([0-9a-f])?$/);
    if (m) return [0, 1, 2].map((i) => parseInt(m[1][i] + m[1][i], 16));
    m = s.match(/^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/);
    if (m) return [m[1], m[2], m[3]].map((n) => Math.round(parseFloat(n)));
    return null;
  };

  const sameColor = (a, b) => {
    const ra = toRgb(a);
    const rb = toRgb(b);
    return !!ra && !!rb && ra.every((c, i) => Math.abs(c - rb[i]) <= 1);
  };

  const chosen = candidates[0];
  map.setConfigProperty(IMPORT_ID, chosen.name, TARGET);

  const readBack = map.getConfigProperty(IMPORT_ID, chosen.name);
  if (sameColor(readBack, TARGET)) {
    console.log('Set "' + chosen.name + '" (' + (chosen.title || 'no title') + ') to ' + TARGET + '. Read back:', readBack);
  } else {
    console.warn(
      'Tried to set "' + chosen.name + '" to ' + TARGET + ', but read back:', readBack,
      'Other candidates:', candidates.slice(1).map((c) => c.name)
    );
  }
})();

