answer:
(() => {
  const IMPORT_ID = 'basemap';
  const TARGET = '#ffd6d6';

  const toColorObj = (c) => {
    if (c && typeof c === 'object' && 'r' in c && 'g' in c && 'b' in c) {
      const a = 'a' in c ? c.a : 1;
      const un = (v) => Math.round((a ? v / a : v) * 255);
      return `rgba(${un(c.r)}, ${un(c.g)}, ${un(c.b)}, ${a})`;
    }
    return c;
  };

  const normalize = (c) => {
    c = toColorObj(c);
    if (typeof c !== 'string') return null;
    const ctx = document.createElement('canvas').getContext('2d');
    ctx.fillStyle = '#010203';
    ctx.fillStyle = c;
    const first = ctx.fillStyle;
    ctx.fillStyle = '#030201';
    ctx.fillStyle = c;
    return first === ctx.fillStyle ? String(first).toLowerCase() : null;
  };

  const wanted = normalize(TARGET);

  let schema = {};
  try {
    schema = map.getSchema(IMPORT_ID) || {};
  } catch (e) {
    schema = {};
  }

  const meta = (entry) => (entry && entry.metadata) || {};
  const haystack = (name, entry) =>
    [name, meta(entry)['mapbox:title'], meta(entry)['mapbox:description']]
      .filter((s) => typeof s === 'string')
      .join(' ')
      .toLowerCase();

  const isColorOption = (name, entry) => {
    const type = entry && entry.type;
    if (typeof type === 'string' && type.toLowerCase() === 'color') return true;
    if (/^colou?r/i.test(name)) return true;
    const h = haystack(name, entry);
    return /\bcolou?r\b/.test(h) && !/\b(show|toggle|visib|enable|font|size|opacity|mode|theme)\b/.test(h);
  };

  const candidates = Object.keys(schema)
    .map((name) => {
      const entry = schema[name];
      const h = haystack(name, entry);
      let score = 0;
      if (name === 'colorMedical') score += 100;
      if (/hospital/.test(h)) score += 50;
      if (/medical|healthcare|health care|\bhealth\b|clinic/.test(h)) score += 30;
      if (/land ?use|grounds|area|polygon|fill/.test(h)) score += 10;
      if (/label|icon|\bpoi\b|text|symbol/.test(h)) score -= 100;
      if (!isColorOption(name, entry)) score -= 1000;
      return { name, score };
    })
    .filter((c) => c.score > 0)
    .sort((a, b) => b.score - a.score);

  let appliedTo = null;

  for (const { name } of candidates) {
    let previous;
    try {
      previous = map.getConfigProperty(IMPORT_ID, name);
    } catch (e) {
      previous = undefined;
    }
    try {
      map.setConfigProperty(IMPORT_ID, name, TARGET);
    } catch (e) {
      continue;
    }
    let readBack;
    try {
      readBack = map.getConfigProperty(IMPORT_ID, name);
    } catch (e) {
      readBack = undefined;
    }
    if (readBack !== undefined && normalize(readBack) === wanted) {
      appliedTo = name;
      break;
    }
    if (previous !== undefined) {
      try {
        map.setConfigProperty(IMPORT_ID, name, previous);
      } catch (e) {}
    }
  }

  if (appliedTo) {
    console.log(`Hospital grounds colour set via config "${IMPORT_ID}.${appliedTo}" =`, map.getConfigProperty(IMPORT_ID, appliedTo));
    return;
  }

  console.warn('No Standard style config setting for hospital/medical grounds colour was found or it did not accept the value; adding an overlay fill layer instead.');

  const SOURCE_ID = 'hospital-grounds-src';
  const LAYER_ID = 'hospital-grounds-fill';

  if (!map.getSource(SOURCE_ID)) {
    map.addSource(SOURCE_ID, {
      type: 'vector',
      url: 'mapbox://mapbox.mapbox-streets-v8'
    });
  }

  if (!map.getLayer(LAYER_ID)) {
    const layer = {
      id: LAYER_ID,
      type: 'fill',
      source: SOURCE_ID,
      'source-layer': 'landuse',
      filter: ['==', ['get', 'class'], 'hospital'],
      paint: {
        'fill-color': TARGET,
        'fill-opacity': 1,
        'fill-emissive-strength': 1
      }
    };
    let slots = [];
    try {
      slots = typeof map.getSlots === 'function' ? map.getSlots() : [];
    } catch (e) {
      slots = [];
    }
    if (!slots.length || slots.includes('bottom')) layer.slot = 'bottom';
    map.addLayer(layer);
  } else {
    map.setPaintProperty(LAYER_ID, 'fill-color', TARGET);
  }
})();

