(function () {
  const IMPORT_ID = 'basemap';
  const TARGET = '#e6d6ff';

  const toRgb = (v) => {
    if (v == null) return null;
    if (typeof v === 'object') {
      if ('r' in v && 'g' in v && 'b' in v) {
        const scale = v.r <= 1 && v.g <= 1 && v.b <= 1 ? 255 : 1;
        return [v.r, v.g, v.b].map((c) => Math.round(c * scale));
      }
      return null;
    }
    const s = String(v).trim().toLowerCase();
    let m = s.match(/^#([0-9a-f]{3})$/);
    if (m) return m[1].split('').map((c) => parseInt(c + c, 16));
    m = s.match(/^#([0-9a-f]{6})([0-9a-f]{2})?$/);
    if (m) return [0, 2, 4].map((i) => parseInt(m[1].slice(i, i + 2), 16));
    m = s.match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/);
    if (m) return [m[1], m[2], m[3]].map((c) => Math.round(parseFloat(c)));
    return null;
  };

  const sameColor = (a, b) => {
    const ra = toRgb(a);
    const rb = toRgb(b);
    return !!ra && !!rb && ra.every((c, i) => Math.abs(c - rb[i]) <= 1);
  };

  const schema = map.getSchema(IMPORT_ID) || {};

  const describe = (name, opt) => {
    const md = (opt && opt.metadata) || {};
    return [name, md['mapbox:title'], md['mapbox:description']]
      .filter(Boolean)
      .join(' ');
  };

  const isColorOption = (name, opt) => {
    if (opt && opt.type) return /colou?r/i.test(String(opt.type));
    if (/^colou?r/i.test(name)) return true;
    return !!toRgb(opt && opt.default);
  };

  const subjectRe = /school|education|universit|college|campus|academ/i;
  const areaRe = /land ?use|area|ground|fill|polygon|zone/i;
  const labelRe = /label|icon|text|poi|point of interest|symbol/i;

  const candidates = Object.keys(schema)
    .map((name) => {
      const opt = schema[name];
      const text = describe(name, opt);
      if (!isColorOption(name, opt) || !subjectRe.test(text)) return null;
      let score = 10;
      if (name === 'colorEducation') score += 100;
      if (areaRe.test(text)) score += 5;
      if (labelRe.test(text)) score -= 20;
      return { name, score, text };
    })
    .filter((c) => c && c.score > 0)
    .sort((a, b) => b.score - a.score);

  const applied = [];
  for (const c of candidates) {
    try {
      map.setConfigProperty(IMPORT_ID, c.name, TARGET);
    } catch (e) {
      console.warn('Failed to set ' + c.name + ':', e);
      continue;
    }
    const readBack = map.getConfigProperty(IMPORT_ID, c.name);
    if (sameColor(readBack, TARGET)) {
      applied.push(c.name);
    } else {
      console.warn('Config "' + c.name + '" did not take the value; read back:', readBack);
    }
  }

  if (applied.length) {
    console.log('School/university grounds colour set via basemap config:', applied.join(', '));
    return;
  }

  console.warn(
    'No basemap config option for school/university grounds colour was found or verified; ' +
      'falling back to a custom fill layer.'
  );

  const SOURCE_ID = 'education-grounds-src';
  const LAYER_ID = 'education-grounds-fill';

  if (!map.getSource(SOURCE_ID)) {
    map.addSource(SOURCE_ID, {
      type: 'vector',
      url: 'mapbox://mapbox.mapbox-streets-v8'
    });
  }

  if (!map.getLayer(LAYER_ID)) {
    map.addLayer({
      id: LAYER_ID,
      type: 'fill',
      slot: 'bottom',
      source: SOURCE_ID,
      'source-layer': 'landuse',
      filter: ['==', ['get', 'class'], 'school'],
      paint: {
        'fill-color': TARGET,
        'fill-opacity': 1
      }
    });
  } else {
    map.setPaintProperty(LAYER_ID, 'fill-color', TARGET);
  }
})();

