(() => {
  const IMPORT_ID = 'basemap';
  const GREY = '#e0e0e0';

  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};
  const meta = (o) => (o && o.metadata) || {};
  const title = (o) => String(meta(o)['mapbox:title'] || '');
  const desc = (o) => String(meta(o)['mapbox:description'] || '');

  const colourEntries = Object.entries(schema).filter(([name, o]) =>
    (o && o.type === 'color') || /^colou?r/i.test(name) || /colou?r/i.test(title(o))
  );

  const findSettings = (re) => {
    let hits = colourEntries.filter(([name, o]) => re.test(name) || re.test(title(o)));
    if (!hits.length) {
      hits = colourEntries.filter(([, o]) => {
        const d = desc(o);
        return re.test(d) && !/\b(except|excluding|excludes|other than|not)\b/i.test(d);
      });
    }
    return hits.map(([name]) => name);
  };

  const isGrey = (v) => {
    if (v == null) return false;
    if (typeof v === 'object' && !Array.isArray(v) && 'r' in v && 'g' in v && 'b' in v) {
      const a = v.a || 1;
      return [v.r, v.g, v.b].every((c) => Math.round((c / a) * 255) === 224);
    }
    const s = (typeof v === 'string' ? v : JSON.stringify(v)).replace(/\s+/g, '').toLowerCase();
    return s.includes('#e0e0e0') || s.includes('rgb(224,224,224)') || s.includes('rgba(224,224,224,1)');
  };

  const targets = {
    industrial: /industr/i,
    airport: /airport|aerodrome|airfield|aviation/i
  };

  const needFallback = [];
  const done = new Set();

  for (const [landuseClass, re] of Object.entries(targets)) {
    let ok = false;
    for (const name of findSettings(re)) {
      if (!done.has(name)) {
        map.setConfigProperty(IMPORT_ID, name, GREY);
        done.add(name);
      }
      const value = map.getConfigProperty(IMPORT_ID, name);
      if (isGrey(value)) {
        ok = true;
        console.log(`[${landuseClass}] ${IMPORT_ID}.${name} =`, value);
      } else {
        console.warn(`[${landuseClass}] ${IMPORT_ID}.${name} did not take the value; read back:`, value);
      }
    }
    if (!ok) needFallback.push(landuseClass);
  }

  if (needFallback.length) {
    console.warn('No working Standard config setting for:', needFallback.join(', '), '- adding a fallback fill layer.');
    const SRC = 'grey-landuse-src';
    const LAYER = 'grey-landuse-fill';
    if (!map.getSource(SRC)) {
      map.addSource(SRC, { type: 'vector', url: 'mapbox://mapbox.mapbox-streets-v8' });
    }
    if (map.getLayer(LAYER)) map.removeLayer(LAYER);
    map.addLayer({
      id: LAYER,
      type: 'fill',
      slot: 'bottom',
      source: SRC,
      'source-layer': 'landuse',
      filter: ['in', ['get', 'class'], ['literal', needFallback]],
      paint: { 'fill-color': GREY, 'fill-opacity': 1 }
    });
  }
})();

