(function () {
  const IMPORT_ID = 'basemap';
  const TARGET = '#8bc34a';
  const TERMS = /\b(green ?spaces?|greenery|green|parks?|parkland|forests?|woods?|woodlands?|vegetation)\b/i;

  const words = (s) => String(s || '')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/[_\-.]+/g, ' ');

  const isColorOption = (name, opt) => {
    const meta = (opt && opt.metadata) || {};
    if (opt && opt.type === 'color') return true;
    if (opt && opt.type && opt.type !== 'string') return false;
    return /^colou?r/i.test(name) || /colou?r/i.test(meta['mapbox:title'] || '');
  };

  const toHex = (v) => {
    if (v == null) return null;
    if (typeof v === 'string') {
      const s = v.replace(/\s+/g, '').toLowerCase();
      const m = s.match(/^rgba?\((\d+),(\d+),(\d+)(?:,([\d.]+))?\)$/);
      if (m) return '#' + [m[1], m[2], m[3]].map((n) => (+n).toString(16).padStart(2, '0')).join('');
      return s;
    }
    if (typeof v === 'object' && 'r' in v && 'g' in v && 'b' in v) {
      const a = v.a || 1;
      return '#' + [v.r, v.g, v.b].map((c) => Math.round((c / a) * 255).toString(16).padStart(2, '0')).join('');
    }
    return JSON.stringify(v);
  };

  const setAndVerify = (name) => {
    map.setConfigProperty(IMPORT_ID, name, TARGET);
    const readBack = map.getConfigProperty(IMPORT_ID, name);
    const ok = toHex(readBack) === TARGET;
    (ok ? console.info : console.warn)(
      `[basemap] ${name} -> ${JSON.stringify(readBack)}${ok ? '' : ' (did not take effect)'}`
    );
    return ok;
  };

  const run = () => {
    const schema = map.getSchema(IMPORT_ID) || {};
    const matches = Object.keys(schema).filter((name) => {
      const opt = schema[name] || {};
      const meta = opt.metadata || {};
      if (!isColorOption(name, opt)) return false;
      const haystack = [words(name), meta['mapbox:title'], meta['mapbox:description']].join(' ');
      return TERMS.test(haystack);
    });

    let applied = matches.filter(setAndVerify);

    if (applied.length === 0) {
      const fallbacks = ['colorGreenspace', 'colorGreenSpace', 'colorParks', 'colorPark'];
      for (const name of fallbacks) {
        const current = map.getConfigProperty(IMPORT_ID, name);
        if (current !== null && current !== undefined && setAndVerify(name)) {
          applied.push(name);
          break;
        }
      }
    }

    if (applied.length === 0) {
      console.warn(
        '[basemap] No greenspace/park/forest colour setting found in the schema. Available settings:',
        Object.keys(schema)
      );
    } else {
      console.info('[basemap] Green areas coloured ' + TARGET + ' via:', applied);
    }
  };

  if (map.isStyleLoaded()) run();
  else map.once('style.load', run);
})();
