(() => {
  const IMPORT_ID = 'basemap';
  const NAVY = '#0b3d91';

  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};

  const meta = (entry, key) => (entry && entry.metadata && entry.metadata[key]) || '';
  const isColorEntry = (name, entry) =>
    !!entry && (entry.type === 'color' || /colou?r/i.test(name) || /colou?r/i.test(meta(entry, 'mapbox:title')));
  const isLabelEntry = (name, entry) =>
    /label|text|icon/i.test(name) || /label|text|icon/i.test(meta(entry, 'mapbox:title'));

  const WATER_RE = /water|sea\b|ocean|lake|river|hydro/i;

  const candidates = Object.keys(schema).filter((n) => isColorEntry(n, schema[n]) && !isLabelEntry(n, schema[n]));

  let waterProps = candidates.filter((n) => WATER_RE.test(n));
  if (!waterProps.length) waterProps = candidates.filter((n) => WATER_RE.test(meta(schema[n], 'mapbox:title')));
  if (!waterProps.length) waterProps = candidates.filter((n) => WATER_RE.test(meta(schema[n], 'mapbox:description')));
  if (!waterProps.length) {
    console.warn('No water colour setting found in the basemap schema; trying "colorWater".');
    waterProps = ['colorWater'];
  }

  const ctx = document.createElement('canvas').getContext('2d');
  const toRGB = (v) => {
    if (v == null) return null;
    if (Array.isArray(v)) {
      if (/^rgba?$/.test(v[0])) return v.slice(1, 4).map(Number);
      if (v.length >= 3 && v.every((x) => typeof x === 'number')) return v.slice(0, 3).map((x) => (x <= 1 ? x * 255 : x));
      return null;
    }
    if (typeof v === 'object' && 'r' in v && 'g' in v && 'b' in v) {
      const a = v.a > 0 ? v.a : 1;
      const s = Math.max(v.r, v.g, v.b) <= 1 ? 255 : 1;
      return [v.r, v.g, v.b].map((x) => (x / a) * s);
    }
    if (typeof v === 'string') {
      ctx.fillStyle = '#000000';
      ctx.fillStyle = v;
      const c = ctx.fillStyle;
      if (c.startsWith('#')) return [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
      const m = c.match(/[\d.]+/g);
      return m ? m.slice(0, 3).map(Number) : null;
    }
    return null;
  };
  const sameColor = (a, b) => {
    const x = toRGB(a), y = toRGB(b);
    return !!x && !!y && x.every((c, i) => Math.abs(c - y[i]) <= 1);
  };

  const results = waterProps.map((name) => {
    map.setConfigProperty(IMPORT_ID, name, NAVY);
    const value = map.getConfigProperty(IMPORT_ID, name);
    return { name, value, ok: sameColor(value, NAVY) };
  });

