(() => {
  const IMPORT_ID = 'basemap';
  const TARGET = '#faf7f0';

  const ctx = document.createElement('canvas').getContext('2d');
  const toCss = (v) => {
    if (v == null) return null;
    if (Array.isArray(v)) {
      const head = typeof v[0] === 'string' ? v[0].toLowerCase() : null;
      const n = v.slice(head ? 1 : 0);
      if (n.length < 3 || n.some((x) => typeof x !== 'number')) return null;
      const a = n.length > 3 ? n[3] : 1;
      if (!head || head === 'rgb' || head === 'rgba') {
        v = `rgba(${Math.round(n[0])},${Math.round(n[1])},${Math.round(n[2])},${a})`;
      } else if (head === 'hsl' || head === 'hsla') {
        v = `hsla(${n[0]},${n[1]}%,${n[2]}%,${a})`;
      } else {
        return null;
      }
    } else if (typeof v === 'object' && 'r' in v && 'g' in v && 'b' in v) {
      const a = v.a ?? 1;
      const c = (x) => Math.round((a ? x / a : x) * 255);
      v = `rgba(${c(v.r)},${c(v.g)},${c(v.b)},${a})`;
    }
    if (typeof v !== 'string') return null;
    const SENTINEL = '#010203';
    ctx.fillStyle = SENTINEL;
    ctx.fillStyle = v;
    const out = String(ctx.fillStyle).toLowerCase();
    return out === SENTINEL && v.trim().toLowerCase() !== SENTINEL ? null : out;
  };

  const meta = (e) => (e && e.metadata) || {};
  const EXCLUDE = /landmark|landuse|label|point\s*of\s*interest|\bpoi|icon|water|road|motorway|trunk|building|green|park|admin|boundar|highlight|select|transit|shadow|fog|sky/i;
  const LAND_TEXT = /\bland\b(?!\s*-?\s*use)/i;

  const isColour = (key, e) => {
    const t = String(e.type ?? meta(e)['mapbox:type'] ?? '').toLowerCase();
    if (t === 'color' || t === 'colour') return true;
    if (t && t !== 'string') return false;
    return toCss(e.default) !== null || /colou?r/i.test(`${key} ${meta(e)['mapbox:title'] || ''}`);
  };

  const score = (key, e) => {
    const title = String(meta(e)['mapbox:title'] || '');
    const desc = String(meta(e)['mapbox:description'] || '');
    if (EXCLUDE.test(key) || EXCLUDE.test(title)) return 0;
    if (!isColour(key, e)) return 0;
    let s = 0;
    if (/^colou?r[_-]?land$|^land[_-]?colou?r$/i.test(key)) s += 100;
    else if (/^colou?r[_-]?background$|^background[_-]?colou?r$/i.test(key)) s += 80;
    else if (/land(?!mark|use|scape|ing)/i.test(key) && !/island/i.test(key)) s += 50;
    else if (/background/i.test(key)) s += 30;
    if (LAND_TEXT.test(title)) s += 40;
    else if (/background/i.test(title)) s += 25;
    if (LAND_TEXT.test(desc)) s += 15;
    if (/background/i.test(desc)) s += 10;
    return s;
  };

  const schema = map.getSchema(IMPORT_ID) || {};
  const candidates = Object.entries(schema)
    .map(([k, e]) => [k, score(k, e || {})])
    .filter(([, s]) => s > 0)
    .sort((a, b) => b[1] - a[1])
    .map(([k]) => k);

  if (!Object.keys(schema).length) {
    candidates.push('colorLand', 'landColor', 'colorBackground', 'backgroundColor');
  }

  const want = toCss(TARGET);
  const trySet = (key) => {
    const before = map.getConfigProperty(IMPORT_ID, key);
    map.setConfigProperty(IMPORT_ID, key, TARGET);
    const after = map.getConfigProperty(IMPORT_ID, key);
    if (toCss(after) === want) return true;
    if (before != null) map.setConfigProperty(IMPORT_ID, key, before);
    return false;
  };

  const applied = candidates.find(trySet);

  if (applied) {
    console.info(`Land colour set via "${IMPORT_ID}" config "${applied}":`, map.getConfigProperty(IMPORT_ID, applied));
  } else {
    console.warn(
      'No land/background colour setting was accepted. Basemap schema:',
      Object.fromEntries(Object.entries(schema).map(([k, e]) => [k, {
        title: meta(e)['mapbox:title'],
        description: meta(e)['mapbox:description'],
        default: e && e.default
      }]))
    );
  }
})();

