  const IMPORT_ID = 'basemap';

  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};

  const searchableText = (name, option) => {
    const meta = (option && option.metadata) || {};
    return [name, meta['mapbox:title'], meta['mapbox:description']]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
  };

  const isBooleanOption = (option) =>
    !!option && (option.type === 'boolean' || typeof option.default === 'boolean');

  const isStreetNameOrShieldOption = (text) =>
    /shield/.test(text) ||
