    (name) => isBooleanOption(schema[name]) && isStreetNameOrShieldOption(searchableText(name, schema[name]))
  );

  if (!targets.includes('showRoadLabels') && (targets.length === 0 || 'showRoadLabels' in schema)) {
    targets.push('showRoadLabels');
