(() => {
  const importId = 'basemap';
  const schema = (typeof map.getSchema === 'function' && map.getSchema(importId)) || {};

  const words = (s) => String(s || '').replace(/([a-z0-9])([A-Z])/g, '$1 $2').replace(/[_-]+/g, ' ').toLowerCase();
  const describe = (name, def) => {
    const md = (def && def.metadata) || {};
    return [words(name), words(md['mapbox:title']), words(md['mapbox:description'])].join(' ');
  };
  const isBoolean = (def) =>
    !!def && (
      def.type === 'boolean' ||
      typeof def.default === 'boolean' ||
      (Array.isArray(def.default) && def.default[0] === 'literal' && typeof def.default[1] === 'boolean')
    );

  const transitRe = /\b(transit|stations?|metro|subway|underground|rail|railways?|trains?|bus|buses|tram|trams)\b/;
  const labelRe = /\b(labels?|icons?|text|names?)\b/;

  const candidates = Object.keys(schema).filter((name) => {
    const def = schema[name];
    if (!isBoolean(def)) return false;
    const d = describe(name, def);
    return transitRe.test(d) && labelRe.test(d);
  });

  if (!candidates.includes('showTransitLabels')) candidates.unshift('showTransitLabels');

  const applied = [];
  const failed = [];

  for (const name of candidates) {
    map.setConfigProperty(importId, name, false);
    let value = map.getConfigProperty(importId, name);
    if (Array.isArray(value) && value[0] === 'literal') value = value[1];
    if (value === false) applied.push(name);
    else failed.push({ name, value });
  }

  if (applied.length) {
    console.log('Transit/station labels hidden via basemap config:', applied);
  } else {
    console.warn('Could not hide transit/station labels: no recognised config setting took effect.', failed, schema);
  }
})();

