const MOTORWAY_COLOR = '#ff6f00';

function findMotorwayColorSetting() {
  const schema = map.getSchema(IMPORT_ID) || {};
  const names = Object.keys(schema);

  if (names.includes('colorMotorways')) return 'colorMotorways';

  const describe = (name) => {
    const meta = (schema[name] && schema[name].metadata) || {};
    return [name, meta['mapbox:title'], meta['mapbox:description']]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
  };

  const candidates = names.filter((name) => {
    const text = describe(name);
    const isColor = (schema[name] && schema[name].type === 'color') || /colou?r/.test(text);
    return isColor && /(motorway|freeway)/.test(text);
  });

  return candidates[0] || null;
}

const motorwaySetting = findMotorwayColorSetting();

if (!motorwaySetting) {
  console.error(
    'No motorway colour setting found in the basemap schema:',
    Object.keys(map.getSchema(IMPORT_ID) || {})
  );
} else {
  map.setConfigProperty(IMPORT_ID, motorwaySetting, MOTORWAY_COLOR);

  const applied = map.getConfigProperty(IMPORT_ID, motorwaySetting);
  if (applied == null) {
    console.error(`Setting "${motorwaySetting}" was not applied (read back: ${applied}).`);
  } else if (typeof applied === 'string' && applied.toLowerCase() !== MOTORWAY_COLOR) {
