const TARGET_COLOR = '#ffb300';

const schema = map.getSchema('basemap') || {};
const entries = Object.entries(schema);

const textOf = (name, entry) => {
  const md = (entry && entry.metadata) || {};
  return {
    name: String(name),
    title: String(md['mapbox:title'] || ''),
    description: String(md['mapbox:description'] || '')
  };
};

const looksLikeColor = (entry) => {
  if (!entry) return false;
  if (String(entry.type || '').toLowerCase() === 'color') return true;
  const d = entry.default;
  return typeof d === 'string' && /^(#|rgb|hsl)/i.test(d.trim());
};

const scored = entries
  .map(([name, entry]) => {
    const t = textOf(name, entry);
    const all = `${t.name} ${t.title} ${t.description}`;
    if (!/trunk/i.test(all)) return null;
    if (/label|text|icon|shield/i.test(all)) return null;
    let score = 0;
    if (/trunk/i.test(t.name)) score += 4;
    if (/trunk/i.test(t.title)) score += 2;
    if (/trunk/i.test(t.description)) score += 1;
    if (/colou?r/i.test(all)) score += 2;
    if (looksLikeColor(entry)) score += 3;
    if (/motorway/i.test(t.name)) score -= 3;
    return { name, entry, score };
  })
  .filter(Boolean)
  .sort((a, b) => b.score - a.score);

const configName = scored.length ? scored[0].name : null;

if (!configName) {
  console.error(
    'No basemap config property for trunk roads was found. Available properties:',
    entries.map(([name, entry]) => ({ name, ...textOf(name, entry) }))
  );
} else {
  map.setConfigProperty('basemap', configName, TARGET_COLOR);

  const normalize = (v) => {
    if (v == null) return null;
    if (typeof v === 'object' && 'r' in v && 'g' in v && 'b' in v) {
      const scale = v.r <= 1 && v.g <= 1 && v.b <= 1 ? 255 : 1;
      const hex = (n) => Math.round(n * scale).toString(16).padStart(2, '0');
      return `#${hex(v.r)}${hex(v.g)}${hex(v.b)}`;
    }
    const s = String(v).trim().toLowerCase().replace(/\s+/g, '');
    const m = s.match(/^rgba?\((\d+),(\d+),(\d+)/);
    if (m) {
      return '#' + m.slice(1, 4).map((n) => Number(n).toString(16).padStart(2, '0')).join('');
    }
    return s;
  };

  const readBack = map.getConfigProperty('basemap', configName);

  if (normalize(readBack) === normalize(TARGET_COLOR)) {
    console.log(`Trunk roads coloured ${TARGET_COLOR} via basemap config "${configName}".`);
  } else {
    console.error(
      `Set basemap config "${configName}" to ${TARGET_COLOR}, but it reads back as`,
      readBack
    );
  }
}

