(function () {
  const IMPORT_ID = 'basemap';
  const COLOR = '#d7ccc8';

  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};
  const EXCLUDE = /motorway|trunk|label|brightness|pedestrian|path|rail|transit|highlight|select|show|density|font|theme|light/i;

  const describe = (name) => {
    const md = (schema[name] && schema[name].metadata) || {};
    return {
      name: String(name),
      title: String(md['mapbox:title'] || ''),
      description: String(md['mapbox:description'] || '')
    };
  };

  const isColorOption = (name) => {
    const opt = schema[name] || {};
    const d = describe(name);
    return opt.type === 'color' || /^colou?r/i.test(d.name) || /colou?r/i.test(d.title) || /colou?r/i.test(d.description);
  };

  const score = (name) => {
    const d = describe(name);
    if (EXCLUDE.test(d.name) || EXCLUDE.test(d.title)) return 0;
    if (!isColorOption(name)) return 0;
    let s = 0;
    if (d.name === 'colorRoads') s += 100;
    if (/road/i.test(d.name)) s += 30;
    if (/road/i.test(d.title)) s += 20;
    if (/road/i.test(d.description)) s += 10;
    return s;
  };

  const candidates = Object.keys(schema)
    .map((name) => ({ name, s: score(name) }))
    .filter((c) => c.s > 0)
    .sort((a, b) => b.s - a.s)
    .map((c) => c.name);

  if (!candidates.includes('colorRoads')) candidates.push('colorRoads');

  const normalize = (v) => String(v == null ? '' : v).toLowerCase().replace(/\s+/g, '');

  let applied = null;
  for (const key of candidates) {
    map.setConfigProperty(IMPORT_ID, key, COLOR);
    const readBack = map.getConfigProperty(IMPORT_ID, key);
    if (readBack != null && normalize(readBack) === normalize(COLOR)) {
      applied = key;
      break;
    }
  }

  if (applied) {
    console.log('Ordinary road colour set via config property "' + applied + '":', map.getConfigProperty(IMPORT_ID, applied));
  } else {
    console.warn('Could not find a road colour config property in the "' + IMPORT_ID + '" schema. Tried:', candidates, 'Schema:', schema);
  }
})();

