(function () {
  const IMPORT_ID = 'basemap';
  const PREFERRED = 'showPedestrianRoads';
  const schema = map.getSchema(IMPORT_ID) || {};
  const lower = (v) => (v == null ? '' : String(v)).toLowerCase();
  const isBooleanEntry = (entry) =>
    !!entry && (entry.type === 'boolean' || typeof entry.default === 'boolean');
  const pattern = /pedestrian|foot\s?path|footway|walkway|sidewalk|trail|\bpaths?\b/;

  const candidates = [];
  if (Object.prototype.hasOwnProperty.call(schema, PREFERRED) && isBooleanEntry(schema[PREFERRED])) {
    candidates.push(PREFERRED);
  }

  for (const [name, entry] of Object.entries(schema)) {
    if (name === PREFERRED || !isBooleanEntry(entry)) continue;
    const meta = entry.metadata || {};
    const haystack = [
      name.replace(/([a-z])([A-Z])/g, '$1 $2'),
      meta['mapbox:title'],
      meta['mapbox:description']
    ].map(lower).join(' | ');
    if (pattern.test(haystack)) candidates.push(name);
  }

  if (candidates.length === 0) {
    console.warn('No basemap config property for footpaths/pedestrian streets/trails was found in the schema:', Object.keys(schema));
    return;
  }

  for (const name of candidates) {
    map.setConfigProperty(IMPORT_ID, name, false);
    const value = map.getConfigProperty(IMPORT_ID, name);
    if (value === false) {
      console.log(`basemap config "${name}" is now`, value);
    } else {
      console.warn(`basemap config "${name}" did not take effect; current value:`, value);
    }
  }
})();

