(() => {
  const IMPORT_ID = 'basemap';

  const get = (name) => {
    try { return map.getConfigProperty(IMPORT_ID, name); } catch (e) { return undefined; }
  };
  const set = (name, value) => {
    try { map.setConfigProperty(IMPORT_ID, name, value); } catch (e) { /* ignore */ }
    return get(name);
  };

  let schema = {};
  try { schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {}; } catch (e) { schema = {}; }

  const entries = Object.keys(schema).map((name) => {
    const def = schema[name] || {};
    const md = def.metadata || {};
    const text = [name, md['mapbox:title'], md['mapbox:description']]
      .filter((s) => typeof s === 'string')
      .join(' ')
      .toLowerCase();
    return { name, def, text };
  });

  const roadRe = /road|street|motorway|trunk|highway/;
  const notLabelRe = /label|text|icon/;

  const lightEntry =
    entries.find((e) => e.name === 'lightPreset') ||
    entries.find((e) => /light|preset|time of day/.test(e.text) &&
      Array.isArray(e.def.values) && e.def.values.some((v) => /night|dusk/i.test(String(v))));
  const lightName = lightEntry ? lightEntry.name : 'lightPreset';

  const readLight = () => {
    let v = get(lightName);
    if (v == null && lightEntry) v = lightEntry.def.default;
    return v;
  };
  const isDarkValue = (v) => /^(dusk|night)$/i.test(String(v));

  let state = null;

  const seen = new Set();
  const candidates = [];
  const addCandidate = (e) => {
    if (e && !seen.has(e.name)) { seen.add(e.name); candidates.push(e); }
  };
  addCandidate(entries.find((e) => e.name === 'roadsBrightness'));
  entries
    .filter((e) => roadRe.test(e.text) && /bright/.test(e.text) && !notLabelRe.test(e.text))
    .forEach(addCandidate);
  if (!seen.has('roadsBrightness') && typeof get('roadsBrightness') === 'number') {
    addCandidate({ name: 'roadsBrightness', def: {}, text: 'roadsbrightness' });
  }

  const numEq = (v, w) => typeof v === 'number' && Math.abs(v - w) < 1e-6;

  for (const c of candidates) {
    const cur = get(c.name);
    const base = typeof cur === 'number' ? cur : (typeof c.def.default === 'number' ? c.def.default : NaN);
    if (!Number.isFinite(base)) continue;
    const min = Number.isFinite(c.def.minValue) ? c.def.minValue : -Infinity;
    const max = Number.isFinite(c.def.maxValue) ? c.def.maxValue : Math.max(1, base * 2);
    if (!(max > base)) continue;
    let target = base + (max - base) * 0.8;
    const step = Number(c.def.stepValue);
    if (step > 0) target = Math.round(target / step) * step;
    target = Math.min(max, Math.max(min, Number(target.toFixed(6))));
    if (!(target > base)) continue;
    const back = set(c.name, target);
    if (typeof back === 'number' && back > base + 1e-9) {
      state = [{ name: c.name, dark: back, normal: base, eq: numEq }];
      break;
    }
    set(c.name, base);
  }

  if (!state) {
    const ctx = document.createElement('canvas').getContext('2d');
    const parse = (v) => {
      if (Array.isArray(v) && /^rgba?$/.test(v[0]) && v.length >= 4) {
        return [+v[1], +v[2], +v[3], v.length > 4 ? +v[4] : 1];
      }
      if (typeof v !== 'string' || !ctx) return null;
      ctx.fillStyle = '#010203';
      ctx.fillStyle = v;
      const s = ctx.fillStyle;
      if (s === '#010203' && v.trim().toLowerCase() !== '#010203') return null;
      let m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(s);
      if (m) return [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16), 1];
      m = /^rgba?\(([^)]+)\)$/.exec(s);
      if (m) {
        const p = m[1].split(',').map(Number);
        return [p[0], p[1], p[2], p.length > 3 ? p[3] : 1];
      }
      return null;
    };
    const toStr = (c) => `rgba(${Math.round(c[0])}, ${Math.round(c[1])}, ${Math.round(c[2])}, ${c[3]})`;
    const colorEq = (a, b) => {
      const pa = parse(a), pb = parse(b);
      return !!pa && !!pb && pa.every((x, i) => Math.abs(x - pb[i]) < (i < 3 ? 2 : 0.02));
    };
    const list = [];
    for (const e of entries) {
      const isColor = e.def.type === 'color' || /color/.test(e.name.toLowerCase());
      if (!isColor || !roadRe.test(e.text) || notLabelRe.test(e.text)) continue;
      const cur = get(e.name);
      const rgba = parse(cur) || parse(e.def.default);
      if (!rgba) continue;
      const normal = typeof cur === 'string' ? cur : toStr(rgba);
      const dark = toStr([
        rgba[0] + (255 - rgba[0]) * 0.45,
        rgba[1] + (255 - rgba[1]) * 0.45,
        rgba[2] + (255 - rgba[2]) * 0.45,
        rgba[3]
      ]);
      const back = set(e.name, dark);
      if (colorEq(back, dark)) list.push({ name: e.name, dark, normal, eq: colorEq });
      set(e.name, normal);
    }
    if (list.length) state = list;
  }

  if (!state) {
    console.warn('No road brightness (or road color) setting was found in the basemap config schema; roads were not changed.');
    return;
  }

  let busy = false;
  const apply = () => {
    if (busy) return;
    const light = readLight();
    if (light == null) return;
    busy = true;
    try {
      const dark = isDarkValue(light);
      for (const s of state) {
        const want = dark ? s.dark : s.normal;
        if (!s.eq(get(s.name), want)) set(s.name, want);
      }
    } finally {
      busy = false;
    }
  };

  apply();
  map.on('styledata', apply);
  map.on('render', apply);
})();

