    const step = Number(c.def.stepValue);
    if (step > 0) target = Math.round(target / step) * step;
    target = Math.min(max, Math.max(min, Number(target.toFixed(6))));
    if (!(target > base)) continue;
    const back = set(c.name, target);
    if (typeof back === 'number' && back > base + 1e-9) {
      state = [{ name: c.name, dark: back, normal: base, eq: numEq }];
      break;
    }
    set(c.name, base);
  }

  if (!state) {
    const ctx = document.createElement('canvas').getContext('2d');
    const parse = (v) => {
      if (Array.isArray(v) && /^rgba?$/.test(v[0]) && v.length >= 4) {
        return [+v[1], +v[2], +v[3], v.length > 4 ? +v[4] : 1];
      }
      if (typeof v !== 'string' || !ctx) return null;
      ctx.fillStyle = '#010203';
      ctx.fillStyle = v;
      const s = ctx.fillStyle;
      if (s === '#010203' && v.trim().toLowerCase() !== '#010203') return null;
      let m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(s);
      if (m) return [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16), 1];
      m = /^rgba?\(([^)]+)\)$/.exec(s);
      if (m) {
        const p = m[1].split(',').map(Number);
        return [p[0], p[1], p[2], p.length > 3 ? p[3] : 1];
      }
      return null;
    };
    const toStr = (c) => `rgba(${Math.round(c[0])}, ${Math.round(c[1])}, ${Math.round(c[2])}, ${c[3]})`;
    const colorEq = (a, b) => {
      const pa = parse(a), pb = parse(b);
      return !!pa && !!pb && pa.every((x, i) => Math.abs(x - pb[i]) < (i < 3 ? 2 : 0.02));
    };
    const list = [];
    for (const e of entries) {
      const isColor = e.def.type === 'color' || /color/.test(e.name.toLowerCase());
      if (!isColor || !roadRe.test(e.text) || notLabelRe.test(e.text)) continue;
      const cur = get(e.name);
      const rgba = parse(cur) || parse(e.def.default);
      if (!rgba) continue;
      const normal = typeof cur === 'string' ? cur : toStr(rgba);
      const dark = toStr([
        rgba[0] + (255 - rgba[0]) * 0.45,
        rgba[1] + (255 - rgba[1]) * 0.45,
        rgba[2] + (255 - rgba[2]) * 0.45,
        rgba[3]
      ]);
      const back = set(e.name, dark);
      if (colorEq(back, dark)) list.push({ name: e.name, dark, normal, eq: colorEq });
      set(e.name, normal);
    }
    if (list.length) state = list;
  }

  if (!state) {
    console.warn('No road brightness (or road color) setting was found in the basemap config schema; roads were not changed.');
    return;
  }

  let busy = false;
  const apply = () => {
    if (busy) return;
    const light = readLight();
    if (light == null) return;
    busy = true;
    try {
      const dark = isDarkValue(light);
      for (const s of state) {
        const want = dark ? s.dark : s.normal;
        if (!s.eq(get(s.name), want)) set(s.name, want);
      }
    } finally {
      busy = false;
    }
  };

  apply();
  map.on('styledata', apply);
  map.on('render', apply);
})();

