(() => {
  const IMPORT_ID = 'basemap';

  let schema = {};
  try {
    schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};
  } catch (e) {
    console.warn('map.getSchema failed:', e);
  }

  const entries = Object.entries(schema).map(([name, def]) => {
    def = def || {};
    const md = def.metadata || {};
    const text = [name, md['mapbox:title'], md['mapbox:description']]
      .filter((v) => typeof v === 'string')
      .join(' | ')
      .toLowerCase();
    return { name, def, text };
  });

  const isPoi = (e) =>
    /point[\s_-]*of[\s_-]*interest|(^|[^a-z])pois?([^a-z]|$)|shop|restaurant|store|retail|food/.test(e.text) ||
    /(^poi|Poi|POI|_poi)/.test(e.name);

  const typeOf = (def) =>
    def.type || (Array.isArray(def.values) ? 'string' : typeof def.default);

  const same = (a, b) => a === b || JSON.stringify(a) === JSON.stringify(b);

  const setAndVerify = (name, value) => {
    try {
      map.setConfigProperty(IMPORT_ID, name, value);
    } catch (e) {
      console.warn(`setConfigProperty("${name}") threw:`, e);
      return false;
    }
    const got = map.getConfigProperty(IMPORT_ID, name);
    const ok = same(got, value);
    if (ok) console.log(`[basemap] ${name} = ${JSON.stringify(got)}`);
    else console.warn(`[basemap] ${name}: set ${JSON.stringify(value)}, read back ${JSON.stringify(got)}`);
    return ok;
  };

  const highestDensityValue = (def) => {
    const t = typeOf(def);
    if (t === 'number') {
      if (typeof def.maxValue === 'number') return def.maxValue;
      if (Array.isArray(def.values) && def.values.length) return Math.max(...def.values.map(Number));
      return undefined;
    }
    if (Array.isArray(def.values) && def.values.length) {
      const ranked = [/max|highest|all|full/i, /dense|high|more|many/i];
      for (const re of ranked) {
        const hit = def.values.find((v) => re.test(String(v)));
        if (hit !== undefined) return hit;
      }
      return def.values[def.values.length - 1];
    }
    return undefined;
  };

  let showOk = false;
  for (const e of entries) {
    const t = typeOf(e.def);
    if (t !== 'boolean' || !isPoi(e) || !/label/.test(e.text)) continue;
    if (/^hide/i.test(e.name)) {
      showOk = setAndVerify(e.name, false) || showOk;
    } else if (/^show/i.test(e.name) || /\bshow|display|visib|enable/.test(e.text)) {
      showOk = setAndVerify(e.name, true) || showOk;
    }
  }
  if (!showOk) {
    showOk = setAndVerify('showPointOfInterestLabels', true);
  }

  let densityOk = false;
  for (const e of entries) {
    if (!/densit/.test(e.text) || !isPoi(e)) continue;
    const value = highestDensityValue(e.def);
    if (value === undefined) {
      console.warn(`[basemap] ${e.name}: could not determine highest density from schema`, e.def);
      continue;
    }
    densityOk = setAndVerify(e.name, value) || densityOk;
  }
  if (!densityOk) {
    const fallbackName = 'densityPointOfInterestLabels';
    const fallbackDef = schema[fallbackName];
    const value = (fallbackDef && highestDensityValue(fallbackDef)) ?? 5;
    densityOk = setAndVerify(fallbackName, value);
  }

  if (!showOk) console.warn('[basemap] Could not confirm that point-of-interest labels are enabled.');
  if (!densityOk) console.warn('[basemap] Could not confirm a point-of-interest label density setting; none was found in the schema.');
})();

