(() => {
  const IMPORT_ID = 'basemap';
  const FALLBACK_KEY = 'fuelingStationModePointOfInterestLabels';
  const FALLBACK_VALUE = 'electric';

  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};

  const metaText = (name, includeDescription = true) => {
    const md = (schema[name] && schema[name].metadata) || {};
    return [name, md['mapbox:title'], includeDescription ? md['mapbox:description'] : null]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
  };

  const FUEL_RE = /fuel|fueling|petrol|gasoline|gas\s*station|charg|electric|\bev\b/;
  const EV_RE = /electric|charg|\bev\b/;
  const PETROL_RE = /petrol|gasoline|\bgas\b|\bfuel\b|diesel/;

  const isEvValue = (v) => {
    const s = String(v).toLowerCase();
    return EV_RE.test(s) && !/both|all|default|any/.test(s);
  };

  const sameValue = (a, b) => JSON.stringify(a) === JSON.stringify(b);

  const apply = (key, value) => {
    map.setConfigProperty(IMPORT_ID, key, value);
    const actual = map.getConfigProperty(IMPORT_ID, key);
    if (!sameValue(actual, value)) {
      console.warn(`Config "${key}" did not take value ${JSON.stringify(value)}; read back ${JSON.stringify(actual)}.`);
      return false;
    }
    return true;
  };

  const candidates = Object.keys(schema).filter((name) => FUEL_RE.test(metaText(name)));

  // Preferred: an enumerated mode setting that offers an EV-charging-only option.
  const modeKey =
    candidates.find((name) => Array.isArray(schema[name].values) && schema[name].values.some(isEvValue) && /mode/i.test(name)) ||
    candidates.find((name) => Array.isArray(schema[name].values) && schema[name].values.some(isEvValue));

  let done = false;

  if (modeKey) {
    const evValue = schema[modeKey].values.find(isEvValue);
    done = apply(modeKey, evValue);
  } else {
    // Alternative: separate boolean toggles for EV charging and petrol stations.
    const booleanKeys = candidates.filter((name) => schema[name].type === 'boolean');
    const evKeys = booleanKeys.filter((name) => EV_RE.test(metaText(name, false)));
    const petrolKeys = booleanKeys.filter((name) => !evKeys.includes(name) && PETROL_RE.test(metaText(name, false)));
    if (evKeys.length || petrolKeys.length) {
      const results = [
        ...evKeys.map((name) => apply(name, true)),
        ...petrolKeys.map((name) => apply(name, false))
      ];
      done = results.length > 0 && results.every(Boolean);
    }
  }

  if (!done && !modeKey && !candidates.length) {
    done = apply(FALLBACK_KEY, FALLBACK_VALUE);
  }

  if (!done) {
    console.warn(
      'Could not confirm a basemap setting that shows only EV charging stations. Fuel-related schema entries:',
      candidates.map((name) => ({ name, entry: schema[name], current: map.getConfigProperty(IMPORT_ID, name) }))
    );
  }
})();

