(() => {
  const importId = 'basemap';
  const knownName = 'backgroundPointOfInterestLabels';
  const schema = (typeof map.getSchema === 'function' && map.getSchema(importId)) || {};

  const describe = (name) => {
    const md = (schema[name] && schema[name].metadata) || {};
    return [name, md['mapbox:title'], md['mapbox:description']]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
  };

  const mentionsPoi = (t) => /\bpoi|point.?of.?interest|points? of interest|icon/.test(t);
  const mentionsBackground = (t) => /background|shape|circle|badge|backdrop/.test(t);

  const offValueFor = (name) => {
    const opt = schema[name] || {};
    if (opt.type === 'boolean' || typeof opt.default === 'boolean') {
      return /^(hide|disable|remove)/i.test(name);
    }
    const values = Array.isArray(opt.values) ? opt.values : [];
    const off = values.find((v) => /^(none|off|hidden|no|false|disabled)$/i.test(String(v)));
    return off !== undefined ? off : 'none';
  };

  const candidates = [];
  if (Object.prototype.hasOwnProperty.call(schema, knownName)) candidates.push(knownName);

  for (const name of Object.keys(schema)) {
    if (candidates.includes(name)) continue;
    const opt = schema[name] || {};
    if (opt.type === 'color' || opt.type === 'number') continue;
    const text = describe(name);
    if (mentionsPoi(text) && mentionsBackground(text)) candidates.push(name);
  }

  if (!candidates.length) candidates.push(knownName);

  let applied = null;
  for (const name of candidates) {
    const value = offValueFor(name);
    map.setConfigProperty(importId, name, value);
    const readBack = map.getConfigProperty(importId, name);
    if (readBack === value) {
      applied = { name, value };
      break;
    }
  }

  if (applied) {
    console.log(`Set ${importId}.${applied.name} =`, applied.value, '(verified with getConfigProperty)');
