(function setSinglePoiLabelColor(map) {
  const importId = 'basemap';
  const teal = '#00897b';
  const knownNames = ['colorPointOfInterestLabels', 'colorPoiLabels', 'colorPointOfInterestLabel', 'colorPoiLabel'];

  const schema = map.getSchema(importId);
  if (!schema || typeof schema !== 'object' || Object.keys(schema).length === 0) {
    throw new Error(`No configuration schema found for import "${importId}".`);
  }

  const describe = (name, option) => {
    const md = (option && option.metadata) || {};
    return [name, md['mapbox:title'], md['mapbox:description']]
      .filter((s) => typeof s === 'string')
      .join(' | ')
      .toLowerCase();
  };

  const POI = /point[\s_-]*of[\s_-]*interest|poi(?!nt)/;
  const COLOR = /colou?r/;
  const SINGLE = /single|one colou?r|uniform|same colou?r/;

  const entries = Object.entries(schema).map(([name, option]) => ({ name, option, text: describe(name, option) }));
  const poiRelated = entries.filter((e) => POI.test(e.text));

  const candidates = poiRelated
    .filter((e) => COLOR.test(e.text))
    .filter((e) => !/mode/i.test(e.name))
    .filter((e) => !(e.option && Array.isArray(e.option.values)))
    .filter((e) => {
      const def = e.option && e.option.default;
      return def === undefined || typeof def !== 'string' || !/^(default|single|none|circle)$/i.test(def);
    })
    .map((e) => {
      const md = (e.option && e.option.metadata) || {};
      let score = 0;
      if (knownNames.includes(e.name)) score += 10;
      if (SINGLE.test(e.text)) score += 5;
      if (/label/.test(e.text)) score += 2;
      if (md['mapbox:type'] === 'color' || (e.option && e.option.type === 'color')) score += 2;
      if (/background|halo|highlight|select|hover/.test(e.text)) score -= 5;
      return { ...e, score };
    })
    .sort((a, b) => b.score - a.score);

  if (candidates.length === 0) {
    throw new Error(
      'No single-colour POI label setting found in the basemap schema. POI-related settings: ' +
        (poiRelated.map((e) => e.name).join(', ') || '(none)')
    );
  }

  if (candidates.length > 1 && candidates[0].score === candidates[1].score) {
    throw new Error(
      'Ambiguous POI label colour setting; candidates: ' +
        candidates.filter((c) => c.score === candidates[0].score).map((c) => c.name).join(', ')
    );
  }

  const propertyName = candidates[0].name;
  map.setConfigProperty(importId, propertyName, teal);

  const readBack = map.getConfigProperty(importId, propertyName);
  const normalized = typeof readBack === 'string' ? readBack.trim().toLowerCase() : JSON.stringify(readBack);
  if (normalized !== teal) {
    throw new Error(`Setting "${propertyName}" did not take effect; read back ${JSON.stringify(readBack)}.`);
  }

  console.info(`Set ${importId}.${propertyName} to ${readBack}.`);
  return propertyName;
})(map);

