  const nameTitle = ([name, spec]) =>
    [name, meta(spec)['mapbox:title']].filter(Boolean).join(' ').toLowerCase();
  const fullText = ([name, spec]) =>
    [name, meta(spec)['mapbox:title'], meta(spec)['mapbox:description']].filter(Boolean).join(' ').toLowerCase();
  const isBool = ([, spec]) =>
    !spec || typeof spec.default === 'boolean' || spec.type === 'checkbox' || spec.type === 'boolean';
  const LABEL_RE = /label|name|text/;

  const landmarkEntries = entries.filter((e) => isBool(e) && /landmark/.test(fullText(e)));

  let iconsKey = 'showLandmarkIcons' in schema ? 'showLandmarkIcons' : null;
  if (!iconsKey) {
    const hit =
      landmarkEntries.find((e) => /icon/.test(nameTitle(e)) && !LABEL_RE.test(nameTitle(e))) ||
      landmarkEntries.find((e) => /icon/.test(fullText(e)) && !LABEL_RE.test(nameTitle(e)));
    iconsKey = hit ? hit[0] : null;
  }

  let labelKey = 'showLandmarkIconLabels' in schema ? 'showLandmarkIconLabels' : null;
  if (!labelKey) {
    const others = landmarkEntries.filter(([n]) => n !== iconsKey);
    const hit =
      others.find((e) => /icon/.test(nameTitle(e)) && LABEL_RE.test(nameTitle(e))) ||
      others.find((e) => LABEL_RE.test(nameTitle(e))) ||
      others.find((e) => LABEL_RE.test(fullText(e)));
    labelKey = hit ? hit[0] : null;
  }

  const setAndVerify = (key, value) => {
    map.setConfigProperty(IMPORT_ID, key, value);
    const actual = map.getConfigProperty(IMPORT_ID, key);
    const ok = actual === value || String(actual) === String(value);
    if (!ok) {
      console.warn(`Config "${key}" did not take effect: expected ${value}, got`, actual);
    }
    return ok;
  };

  if (iconsKey) {
    setAndVerify(iconsKey, true);
  } else {
    console.warn('No landmark icon setting found in basemap schema. Candidates:', landmarkEntries.map(([n]) => n));
