  const mentions3d = (e) =>
    /3d/i.test(e.name) || /\b3d\b|three[\s-]?dimensional/i.test(e.title + ' ' + e.desc);
  const isNegated = (e) => /hide|disable|2d/i.test(e.name);

  const master =
    entries.find((e) => /^show3dobjects$/i.test(e.name)) ||
    entries.find(
      (e) =>
        isBoolean(e) &&
        /\b(all|every(thing)?)\b[^.]*\b3d\b|\b3d\s+objects\b/i.test(e.title + ' ' + e.desc)
    );

  const targets = new Set();
  if (master) targets.add(master.name);
  entries
    .filter((e) => isBoolean(e) && mentions3d(e) && !isNegated(e))
    .forEach((e) => targets.add(e.name));

  if (targets.size === 0) {
    ['show3dObjects', 'show3dBuildings', 'show3dLandmarks', 'show3dTrees', 'show3dFacades'].forEach(
      (n) => targets.add(n)
    );
  }

  targets.forEach((name) => map.setConfigProperty(importId, name, false));

  const normalize = (v) => (Array.isArray(v) && v[0] === 'literal' ? v[1] : v);
  const results = {};
  targets.forEach((name) => {
    results[name] = normalize(map.getConfigProperty(importId, name));
  });

  const confirmedOff = Object.keys(results).filter((n) => results[n] === false);
  const notApplied = Object.keys(results).filter((n) => results[n] !== false);

  if (confirmedOff.length === 0) {
    console.error('No 3D setting could be turned off on "' + importId + '". Read-back values:', results);
  } else if (master && results[master.name] !== false) {
    console.error('Master 3D setting "' + master.name + '" did not read back as false:', results);
  } else if (notApplied.length) {
    console.warn('3D turned off via ' + confirmedOff.join(', ') + '; settings not recognized or not applied:', notApplied);
  } else {
    console.log('3D turned off; verified false:', confirmedOff.join(', '));
  }

  return results;
})();

