  const findSetting = (word, avoid) => {
    let best = null;
    let bestScore = 0;
    for (const e of entries) {
      let score = 0;
      if (e.n.includes(word) && is3d(e.n)) score += 8;
      else if (e.n.includes(word)) score += 4;
      if (e.title.includes(word)) score += is3d(e.title) ? 4 : 2;
      if (e.description.includes(word)) score += is3d(e.description) ? 2 : 1;
      if (score === 0) continue;
      const head = `${e.n} ${e.title}`;
      if (avoid.some(a => head.includes(a))) score -= 10;
      if (score > bestScore) {
        bestScore = score;
        best = e.name;
      }
    }
    return bestScore > 0 ? best : null;
  };

  const unwrap = v => (Array.isArray(v) && v[0] === 'literal' ? v[1] : v);

