  if (treesKey && treesKey !== buildingsKey) setAndVerify(treesKey, true);
  if (landmarksKey && landmarksKey !== buildingsKey) setAndVerify(landmarksKey, true);
  setAndVerify(buildingsKey, false);

  console.log('Mapbox Standard config applied:', {
    [buildingsKey]: unwrap(map.getConfigProperty(IMPORT_ID, buildingsKey)),
    ...(treesKey ? { [treesKey]: unwrap(map.getConfigProperty(IMPORT_ID, treesKey)) } : {}),
    ...(landmarksKey ? { [landmarksKey]: unwrap(map.getConfigProperty(IMPORT_ID, landmarksKey)) } : {}),
    ...(masterKey ? { [masterKey]: unwrap(map.getConfigProperty(IMPORT_ID, masterKey)) } : {})
  });
})();

