(() => {
  const IMPORT_ID = 'basemap';
  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};
  const entries = Object.entries(schema);

  const describe = (name, def) => [
    name,
    def && def.metadata && def.metadata['mapbox:title'],
    def && def.metadata && def.metadata['mapbox:description']
  ].filter(Boolean).join(' ').toLowerCase();

  const isBoolean = (def) => !!def && (def.type === 'boolean' || typeof def.default === 'boolean');

  const enable = (name) => {
    map.setConfigProperty(IMPORT_ID, name, true);
    return map.getConfigProperty(IMPORT_ID, name) === true;
  };

  // Facades are drawn on 3D buildings, so make sure those are on first.
  const prerequisites = entries
    .filter(([name, def]) => isBoolean(def) && (
      name === 'show3dObjects' ||
      name === 'show3dBuildings' ||
      /\b3d (objects|buildings)\b/.test(describe(name, def).replace(/show3d/g, '3d '))
    ))
    .map(([name]) => name);
  for (const name of prerequisites) {
    if (!enable(name)) console.warn(`Could not enable "${name}" on "${IMPORT_ID}".`);
  }

  // Find the facade setting by name, title or description.
  let facadeKeys = entries
    .filter(([name, def]) => isBoolean(def) && /fa[cç]ade/.test(describe(name, def)))
    .map(([name]) => name);

  if (!facadeKeys.length) {
    facadeKeys = entries
      .filter(([name, def]) => isBoolean(def) && /window|texture/.test(describe(name, def)))
      .map(([name]) => name);
  }

  // If the schema was unavailable, fall back to the documented name.
  if (!facadeKeys.length && !entries.length) facadeKeys = ['show3dFacades'];

  if (!facadeKeys.length) {
    console.warn(`No 3D facade setting found in the "${IMPORT_ID}" schema.`, Object.keys(schema));
