  for (const name of facadeKeys) {
    if (enable(name)) {
      console.log(`3D building facades enabled via "${name}".`);
    } else {
      console.warn(`Setting "${name}" did not take effect; current value:`, map.getConfigProperty(IMPORT_ID, name));
    }
  }
})();

