(() => {
  const IMPORT_ID = 'basemap';
  const TARGET = '#cfe8ff';

  const toRgb = (value) => {
    if (value == null) return null;
    if (typeof value === 'object' && 'r' in value && 'g' in value && 'b' in value) {
      const scale = value.r <= 1 && value.g <= 1 && value.b <= 1 ? 255 : 1;
      return [value.r, value.g, value.b].map((c) => Math.round(c * scale));
    }
    const s = String(value).trim().toLowerCase();
    let m = s.match(/^#([0-9a-f]{3,8})$/);
    if (m) {
      let h = m[1];
      if (h.length === 3 || h.length === 4) h = h.split('').map((c) => c + c).join('');
      return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
    }
    m = s.match(/^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
    if (m) return m.slice(1, 4).map((c) => Math.round(parseFloat(c)));
    return null;
  };

  const sameColor = (a, b) => {
    const ra = toRgb(a);
    const rb = toRgb(b);
    return !!ra && !!rb && ra.every((c, i) => Math.abs(c - rb[i]) <= 1);
  };

  const schema = map.getSchema(IMPORT_ID) || {};
  const EXCLUDE = /highlight|select|hover|press|active|label|icon|text/i;

  const entries = Object.entries(schema).map(([name, def]) => {
    const md = (def && def.metadata) || {};
    return {
      name,
      def: def || {},
      title: md['mapbox:title'] || '',
      description: md['mapbox:description'] || ''
    };
  });

  const buildingRelated = entries.filter(({ name, title, description }) =>
    /building/i.test(`${name} ${title} ${description}`)
  );

  const candidates = buildingRelated
    .filter(({ name, title, def }) => {
      const isColor =
        def.type === 'color' ||
        /colou?r/i.test(`${name} ${title}`) ||
        toRgb(def.default) !== null;
      return isColor && !EXCLUDE.test(`${name} ${title}`);
    })
    .map((e) => ({
      ...e,
      score:
        (e.name === 'colorBuildings' ? 100 : 0) +
        (/building/i.test(e.name) ? 10 : 0) +
        (/building/i.test(e.title) ? 5 : 0) +
        (/colou?r/i.test(e.name) ? 2 : 0) +
        (/colou?r/i.test(e.title) ? 1 : 0)
    }))
    .sort((a, b) => b.score - a.score);

  for (const { name } of candidates) {
    const previous = map.getConfigProperty(IMPORT_ID, name);
    map.setConfigProperty(IMPORT_ID, name, TARGET);
    const readBack = map.getConfigProperty(IMPORT_ID, name);
    if (sameColor(readBack, TARGET)) {
      console.info(`Buildings coloured ${TARGET} via config property "${name}" (read back: ${JSON.stringify(readBack)}).`);
      return;
    }
    if (previous !== undefined) map.setConfigProperty(IMPORT_ID, name, previous);
  }

  console.warn(
    `Could not find or verify a building colour setting in the "${IMPORT_ID}" import schema. Building-related entries:`,
    buildingRelated.map(({ name, title, description, def }) => ({
      name,
      title,
      description,
      type: def.type,
      default: def.default
    }))
  );
})();

