  const IMPORT_ID = 'basemap';
  const schema = map.getSchema(IMPORT_ID) || {};
  const TREE_RE = /tree/i;

  const str = (v) => (typeof v === 'string' ? v : '');
  const meta = (entry) => (entry && entry.metadata) || {};

  const isBooleanSetting = (key, entry) => {
    if (entry && entry.type === 'boolean') return true;
    if (entry && typeof entry.default === 'boolean') return true;
    return typeof map.getConfigProperty(IMPORT_ID, key) === 'boolean';
  };

  const keys = Object.keys(schema).filter((key) => isBooleanSetting(key, schema[key]));

  const byName = keys.filter((key) => TREE_RE.test(key));
  const byTitle = keys.filter((key) => TREE_RE.test(str(meta(schema[key])['mapbox:title'])));
  const byDescription = keys.filter((key) => TREE_RE.test(str(meta(schema[key])['mapbox:description'])));

  const candidates =
    byName.length ? byName :
    byTitle.length ? byTitle :
    byDescription;

  if (!candidates.length) {
    console.warn('No 3D tree setting was found in the basemap schema.', Object.keys(schema));
    return;
  }

  if (candidates === byDescription) {
    console.warn('Only broader settings mention trees; turning these off may also hide other 3D objects:', candidates);
  }

  for (const key of candidates) {
    const label = `${key} ${str(meta(schema[key])['mapbox:title'])}`;
