(() => {
  const IMPORT_ID = 'basemap';
  const schema = map.getSchema(IMPORT_ID);
  if (!schema || typeof schema !== 'object') {
    throw new Error('No config schema found for import "' + IMPORT_ID + '".');
  }

  const names = Object.keys(schema);

  const describe = (name) => {
    const md = (schema[name] && schema[name].metadata) || {};
    return {
      name: name.toLowerCase(),
      title: String(md['mapbox:title'] || '').toLowerCase(),
      description: String(md['mapbox:description'] || '').toLowerCase()
    };
  };

  const isBoolean = (name) =>
    typeof (schema[name] && schema[name].default) === 'boolean' ||
    typeof map.getConfigProperty(IMPORT_ID, name) === 'boolean';

  const mentions3d = (s) => /3d|3-d|three[- ]dimensional|model/.test(s);

  // Settings that are not the landmark-model switch (icons/labels, master switches, other 3D object types).
  const excludedFromLandmark = /icon|label|poi|object|building|tree|facade|color|colour/;

  const scoreLandmark = (name) => {
    if (!isBoolean(name)) return 0;
    const d = describe(name);
    if (excludedFromLandmark.test(d.name)) return 0;
