(() => {
  const importId = 'basemap';
  const schema = (typeof map.getSchema === 'function' && map.getSchema(importId)) || {};

  const norm = (s) => String(s || '')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/[_\-]+/g, ' ')
    .toLowerCase();

  const INDOOR = /\bindoors?\b|\bfloor\s*plans?\b|\bfloorplans?\b|\bfloors?\b/;
  const LABEL = /\blabels?\b|\btext\b/;

  const meta = (spec) => (spec && spec.metadata) || {};
  const titleText = (name, spec) => norm(name + ' ' + (meta(spec)['mapbox:title'] || ''));
  const descText = (spec) => norm(meta(spec)['mapbox:description'] || '');

  const entries = Object.entries(schema);

  let matches = entries.filter(([name, spec]) => {
    const t = titleText(name, spec);
    return INDOOR.test(t) && LABEL.test(t);
  });

  if (!matches.length) {
    matches = entries.filter(([name, spec]) => {
      const t = titleText(name, spec);
      const d = descText(spec);
      return LABEL.test(t) && !INDOOR.test(t) && INDOOR.test(d) && !/\ball\b/.test(d + ' ' + t);
    });
  }

  const hiddenValueFor = (name, spec) => {
    const words = titleText(name, spec);
    if (spec.type === 'boolean' || typeof spec.default === 'boolean') {
      return /\bhide|\bhidden|\bdisable/.test(words);
    }
    if (Array.isArray(spec.values)) {
      const v = spec.values.find((x) => /^(none|hidden|hide|off|disabled?|false)$/i.test(String(x)));
      if (v !== undefined) return v;
    }
    return undefined;
  };

  const same = (a, b) => a === b || JSON.stringify(a) === JSON.stringify(b);
  const applied = [];

  for (const [name, spec] of matches) {
    const value = hiddenValueFor(name, spec);
    if (value === undefined) continue;
    map.setConfigProperty(importId, name, value);
    const readBack = map.getConfigProperty(importId, name);
    if (same(readBack, value)) {
      applied.push(name);
    } else {
      console.warn(`Config "${name}" did not take effect (read back: ${JSON.stringify(readBack)})`);
    }
  }

  if (!applied.length) {
    const candidates = [
      'showIndoorLabels',
      'showIndoorFloorplanLabels',
      'showIndoorFloorPlanLabels',
      'showFloorplanLabels',
      'showFloorPlanLabels'
    ];
    for (const name of candidates) {
      if (matches.some(([n]) => n === name)) continue;
      map.setConfigProperty(importId, name, false);
      if (map.getConfigProperty(importId, name) === false) {
        applied.push(name);
        break;
      }
    }
  }

  if (applied.length) {
    console.log('Indoor floor plan labels hidden via:', applied.map((n) => `${n}=${JSON.stringify(map.getConfigProperty(importId, n))}`).join(', '));
  } else {
    console.warn('No indoor floor plan label setting found in the basemap schema:', Object.keys(schema));
  }
})();

