(() => {
  const IMPORT_ID = 'basemap';
  const TARGET_COLOR = '#ff00ff';
  const PREFERRED = 'colorPlaceLabelHighlight';

  const schema = (map.getSchema && map.getSchema(IMPORT_ID)) || {};
  const names = Object.keys(schema);

  const words = (s) =>
    String(s || '')
      .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
      .replace(/[_\-.]+/g, ' ')
      .toLowerCase();

  const meta = (name) => (schema[name] && schema[name].metadata) || {};
  const nameAndTitle = (name) => words(name) + ' ' + words(meta(name)['mapbox:title']);
  const fullText = (name) => nameAndTitle(name) + ' ' + words(meta(name)['mapbox:description']);

  const isColorOption = (name) => {
    const entry = schema[name] || {};
    if (entry.type === 'color') return true;
    if (/\bcolou?r\b/.test(nameAndTitle(name))) return true;
    return typeof entry.default === 'string' && /^(#|rgb|hsl)/i.test(entry.default.trim());
  };

  const score = (name) => {
    if (!isColorOption(name)) return -1;
    const head = nameAndTitle(name);
    const all = fullText(name);
    if (!/\bhighlight/.test(all)) return -1;
    if (/\bselect/.test(head) && !/\bhighlight/.test(head)) return -1;
    if (/\b(poi|pois|building|buildings|landmark|landmarks|road|roads|transit)\b/.test(head)) return -1;
    let s = 0;
    if (/\bplace/.test(head)) s += 4;
    else if (/\bplace/.test(all)) s += 2;
    if (/\blabel/.test(head)) s += 3;
    else if (/\blabel/.test(all) || /\bname/.test(all)) s += 1;
    if (/\bhighlight/.test(head)) s += 2;
    return s;
  };

  const ctx = document.createElement('canvas').getContext('2d');
  const normalizeColor = (v) => {
    if (v == null) return '';
    if (Array.isArray(v)) {
      if ((v[0] === 'literal' || v[0] === 'to-color') && v.length === 2) return normalizeColor(v[1]);
      if ((v[0] === 'rgba' || v[0] === 'rgb') && v.length >= 4) {
        v = 'rgba(' + v[1] + ',' + v[2] + ',' + v[3] + ',' + (v.length > 4 ? v[4] : 1) + ')';
      } else {
        return JSON.stringify(v);
      }
    }
    ctx.fillStyle = '#010203';
    ctx.fillStyle = String(v);
    const out = String(ctx.fillStyle).toLowerCase();
    return out === '#010203' && String(v).toLowerCase() !== '#010203' ? '' : out;
  };
  const target = normalizeColor(TARGET_COLOR);

  const candidates = [];
  if (names.includes(PREFERRED)) candidates.push(PREFERRED);
  names
    .filter((n) => n !== PREFERRED)
    .map((n) => ({ n, s: score(n) }))
    .filter((c) => c.s >= 6)
    .sort((a, b) => b.s - a.s)
    .forEach((c) => candidates.push(c.n));
  if (!candidates.length) candidates.push(PREFERRED);

  let applied = null;
  for (const name of candidates) {
    const previous = map.getConfigProperty(IMPORT_ID, name);
    map.setConfigProperty(IMPORT_ID, name, TARGET_COLOR);
    const readBack = map.getConfigProperty(IMPORT_ID, name);
    if (readBack != null && normalizeColor(readBack) === target) {
      applied = name;
      break;
    }
    if (previous != null) map.setConfigProperty(IMPORT_ID, name, previous);
  }

  if (applied) {
    console.log('[place-label highlight] "' + IMPORT_ID + '" config "' + applied + '" =', map.getConfigProperty(IMPORT_ID, applied));
  } else {
    console.warn(
      '[place-label highlight] Could not find/verify a place-label highlight color setting in the "' + IMPORT_ID + '" schema. Tried:',
      candidates,
      'Available color settings:',
      names.filter(isColorOption).map((n) => ({ name: n, title: meta(n)['mapbox:title'], description: meta(n)['mapbox:description'] }))
    );
  }
})();

