(() => {
  const IMPORT_ID = 'basemap';
  const COLOR = '#ffeb3b';

  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};

  const describe = (name, def) => {
    const md = (def && def.metadata) || {};
    return [name, md['mapbox:title'], md['mapbox:description']]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
  };

  const looksLikeColor = (v) =>
    typeof v === 'string' && /^(#|rgb|hsl)/i.test(v.trim());

  const score = (name, def) => {
    const text = describe(name, def);
    const lname = name.toLowerCase();
    if (!/building/.test(text) || !/highlight/.test(text)) return -Infinity;
    let s = 0;
    if (name === 'colorBuildingHighlight') s += 100;
    if (/building/.test(lname) && /highlight/.test(lname)) s += 50;
    if (/^colou?r/.test(lname) || /colou?r/.test(text)) s += 20;
    if (def && looksLikeColor(def.default)) s += 10;
    if (/select/.test(lname)) s -= 60;
    if (/^show|enable|toggle/.test(lname)) s -= 40;
    return s;
  };

  const candidates = Object.entries(schema)
    .map(([name, def]) => ({ name, s: score(name, def) }))
    .filter((c) => c.s > -Infinity)
    .sort((a, b) => b.s - a.s)
    .map((c) => c.name);

  if (!candidates.includes('colorBuildingHighlight') && !Object.keys(schema).length) {
    candidates.push('colorBuildingHighlight');
  }

  const matches = (value) => {
    if (value == null) return false;
    if (typeof value === 'string') return value.trim().toLowerCase() === COLOR;
    if (typeof value === 'object' && 'r' in value && 'g' in value && 'b' in value) {
      const to255 = (n) => Math.round((n <= 1 ? n * 255 : n));
      const hex = '#' + [value.r, value.g, value.b]
        .map((n) => to255(n).toString(16).padStart(2, '0'))
        .join('');
      return hex.toLowerCase() === COLOR;
    }
    return String(value).trim().toLowerCase() === COLOR;
  };

  for (const name of candidates) {
    map.setConfigProperty(IMPORT_ID, name, COLOR);
    const readBack = map.getConfigProperty(IMPORT_ID, name);
    if (matches(readBack)) {
      console.info(`Building highlight colour set via "${name}" =`, readBack);
      return;
    }
  }

  console.warn(
    'Could not find a building highlight colour setting in the basemap schema. Available settings:',
    Object.keys(schema)
  );
})();

