      .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
      .replace(/[^a-zA-Z0-9]+/g, ' ')
      .toLowerCase();

  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};

  const entries = Object.entries(schema).map(([name, opt]) => {
    const o = opt || {};
    const md = o.metadata || {};
    return {
      name,
      opt: o,
      nameText: norm(name),
      text: [name, md['mapbox:title'], md['mapbox:description']].map(norm).join(' ')
    };
  });

  const isColorOption = (e) =>
    !['boolean', 'number'].includes(e.opt.type) && !Array.isArray(e.opt.values);

  const notOtherState = (e) =>
    !/select|press|active|click/.test(e.nameText) &&
    !/halo|opacity|width|size|outline|stroke/.test(e.nameText);

  let candidates = entries.filter(
    (e) =>
      isColorOption(e) &&
      notOtherState(e) &&
      /\bindoor/.test(e.text) &&
      /\blabel/.test(e.text) &&
      /highlight/.test(e.text)
  );

  if (!candidates.length) {
    candidates = entries.filter(
      (e) => isColorOption(e) && notOtherState(e) && /\bindoor/.test(e.text) && /highlight/.test(e.text)
    );
  }

  let names = candidates.map((e) => e.name);
  if (!names.length) {
    names = ['colorIndoorLabelHighlight', 'colorIndoorHighlight', 'colorIndoorLabelsHighlight'];
  }

  const isTarget = (v) => {
