(function setIndoorLabelSelectColor() {
  const schema = map.getSchema(IMPORT_ID) || {};
  const norm = (s) => String(s == null ? '' : s).toLowerCase();

  const isColorEntry = (def) => {
    if (!def) return false;
    if (norm(def.type) === 'color') return true;
    const d = def.default;
    return typeof d === 'string' && /^(#|rgb|hsl)/i.test(d.trim());
  };

  const scored = Object.entries(schema)
    .map(([name, def]) => {
      const meta = (def && def.metadata) || {};
      const title = norm(meta['mapbox:title']);
      const desc = norm(meta['mapbox:description']);
      const lname = norm(name);
      const text = `${lname} ${title} ${desc}`;

