      if (!/indoor/.test(text)) return null;
      if (!/label/.test(text)) return null;
      if (!/select/.test(text)) return null;

      let score = 0;
      if (/indoor/.test(lname)) score += 4;
      if (/label/.test(lname)) score += 4;
      if (/select/.test(lname)) score += 4;
      if (/colou?r/.test(lname)) score += 1;
      if (/indoor/.test(title)) score += 2;
