      if (/highlight|hover/.test(title) && !/select/.test(title)) score -= 3;
      if (/background|halo|icon/.test(lname)) score -= 2;
      return { name, score, title: meta['mapbox:title'], description: meta['mapbox:description'] };
    })
    .filter(Boolean)
