  map.setConfigProperty(IMPORT_ID, best.name, TARGET_COLOR);

  const readBack = map.getConfigProperty(IMPORT_ID, best.name);
  const readBackStr = norm(
    readBack && typeof readBack === 'object' && typeof readBack.toString === 'function' && !Array.isArray(readBack)
      ? readBack.toString()
      : Array.isArray(readBack) && readBack[0] === 'literal'
        ? readBack[1]
        : readBack
  );

  if (readBackStr === norm(TARGET_COLOR)) {
    console.log(`Set ${IMPORT_ID}.${best.name} = ${TARGET_COLOR}`, best);
  } else {
    console.warn(
      `Tried to set ${IMPORT_ID}.${best.name} to ${TARGET_COLOR}, but getConfigProperty returned:`,
      readBack,
      'Other candidates:',
      scored.slice(1)
    );
  }
})();

